   fn is_marked_section(path: &str) -> bool {
       path.strip_prefix("spec/")
           .and_then(|name| name.split_once('-'))
           .and_then(|(number, _)| number.parse::<u32>().ok())
           .is_some_and(|number| MARKED_SECTIONS.contains(&number))
